// ok(x): 길이 x로 잘라 K개 이상 얻을 수 있는가 (x가 커질수록 어려워진다)
long long lo = 0, hi = 1LL << 31;  // lo는 항상 가능, hi는 항상 불가능
while (hi - lo > 1) {
    long long mid = (lo + hi) / 2;
    if (ok(mid)) lo = mid;
    else hi = mid;
}
// 답은 lo

